1	package org.springframework.samples.petclinic.util;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	import org.springframework.samples.petclinic.model.Owner;
8	
9	/**
10	 * Derives an owner's {@code customerCode} - the single region-and-hash identity every other
11	 * derived value (membership number, check digit, locality, create audit line) is built from.
12	 *
13	 * <p>The code is formatted {@code <REGION>-<HASH8>} where REGION is the region derived from the
14	 * owner's postcode (via the shared {@link Locality} derivation, which prefers the postcode and
15	 * falls back to the city) and HASH8 is the first eight UPPER-case hex characters of SHA-256 over
16	 * the concatenation of the owner's normalized (E.164) telephone and last name. The per-city
17	 * sequence numbers of the old {@code <CITY3>-<LAST3>-<NNNN>} format are gone: the code no longer
18	 * depends on how many owners already exist, so it is a pure function of the owner's own fields.
19	 */
20	public final class CustomerCode {
21	
22	    private CustomerCode() {
23	    }
24	
25	    /**
26	     * Builds the {@code <REGION>-<HASH8>} customer code for {@code owner}. The telephone is read
27	     * in its already-normalized E.164 form, so the hash matches the stored telephone.
28	     *
29	     * @param owner the owner whose customer code to build.
30	     * @return the region-and-hash customer code.
31	     */
32	    public static String of(Owner owner) {
33	        String region = Locality.of(owner.getPostcode(), owner.getCity());
34	        return region + "-" + hash8(owner.getTelephone(), owner.getLastName());
35	    }
36	
37	    /**
38	     * The region segment of an owner's identity - the region encoded in the {@code customerCode}
39	     * when one has been assigned, otherwise the shared {@link Locality} derivation so owners
40	     * without a code (e.g. legacy seed data) still resolve a region.
41	     *
42	     * @param owner the owner whose region to derive.
43	     * @return the region, or {@code "UNKNOWN"} when it cannot be resolved.
44	     */
45	    public static String regionOf(Owner owner) {
46	        String code = owner.getCustomerCode();
47	        if (code == null || code.isBlank()) {
48	            return Locality.of(owner.getPostcode(), owner.getCity());
49	        }
50	        int dash = code.indexOf('-');
51	        return dash < 0 ? code : code.substring(0, dash);
52	    }
53	
54	    /** First eight UPPER-case hex characters of SHA-256 over {@code telephone + lastName}. */
55	    private static String hash8(String telephone, String lastName) {
56	        String input = safe(telephone) + safe(lastName);
57	        try {
58	            byte[] digest = MessageDigest.getInstance("SHA-256")
59	                    .digest(input.getBytes(StandardCharsets.UTF_8));
60	            StringBuilder sb = new StringBuilder();
61	            for (int i = 0; i < 4; i++) {
62	                sb.append(String.format("%02X", digest[i]));
63	            }
64	            return sb.toString();
65	        }
66	        catch (NoSuchAlgorithmException ex) {
67	            throw new IllegalStateException("SHA-256 not available", ex);
68	        }
69	    }
70	
71	    private static String safe(String value) {
72	        return value == null ? "" : value;
73	    }
74	}
