1	package org.springframework.samples.petclinic.util;
2	
3	/**
4	 * Computes the Luhn check digit over the digits contained in a string. Non-digit characters are
5	 * ignored, so the customer code separators ({@code -}) do not contribute. This is the standard
6	 * Luhn algorithm: doubling every second digit from the right and reducing any result above nine
7	 * by nine, then returning the digit that makes the total a multiple of ten.
8	 */
9	public final class CheckDigit {
10	
11	    private CheckDigit() {
12	    }
13	
14	    /**
15	     * @param value the string whose contained digits to check.
16	     * @return the Luhn check digit (0-9) over the digits in {@code value}.
17	     */
18	    public static int luhn(String value) {
19	        int sum = 0;
20	        boolean dbl = true;
21	        for (int i = value.length() - 1; i >= 0; i--) {
22	            char c = value.charAt(i);
23	            if (c < '0' || c > '9') {
24	                continue;
25	            }
26	            int d = c - '0';
27	            if (dbl) {
28	                d *= 2;
29	                if (d > 9) {
30	                    d -= 9;
31	                }
32	            }
33	            sum += d;
34	            dbl = !dbl;
35	        }
36	        return (10 - (sum % 10)) % 10;
37	    }
38	}
