1	package org.springframework.samples.petclinic.util;
2	
3	import java.time.LocalDate;
4	import java.time.Month;
5	
6	/**
7	 * Derives fiscal-year values from a date. The fiscal year starts on 1 July: a date on or after
8	 * 1 July belongs to the fiscal year named for that calendar year, a date before 1 July belongs to
9	 * the fiscal year named for the previous calendar year (e.g. 2026-03-15 is fiscal year 2025).
10	 *
11	 * <p>The inputs are the business-day-adjusted registration date, so every derived value (the
12	 * {@code fiscalYear} label, the membership number's year segment, tenure) shares one basis.
13	 */
14	public final class FiscalYear {
15	
16	    /** First month of the fiscal year. */
17	    private static final Month FISCAL_START = Month.JULY;
18	
19	    private FiscalYear() {
20	    }
21	
22	    /**
23	     * The starting calendar year of the fiscal year that contains {@code date}: the date's own year
24	     * from 1 July onward, otherwise the previous year.
25	     */
26	    public static int startYear(LocalDate date) {
27	        int year = date.getYear();
28	        return date.getMonthValue() >= FISCAL_START.getValue() ? year : year - 1;
29	    }
30	
31	    /** The two-digit year segment (fiscal start year mod 100) for the fiscal year of {@code date}. */
32	    public static int yearSegment(LocalDate date) {
33	        return startYear(date) % 100;
34	    }
35	
36	    /** The {@code 'FY<YY>'} label for the fiscal year that contains {@code date}. */
37	    public static String label(LocalDate date) {
38	        return String.format("FY%02d", yearSegment(date));
39	    }
40	
41	    /**
42	     * Elapsed fiscal years between {@code from} and {@code to}: the number of 1-July boundaries
43	     * crossed, i.e. the difference of their fiscal start years.
44	     */
45	    public static long elapsed(LocalDate from, LocalDate to) {
46	        return startYear(to) - startYear(from);
47	    }
48	}
