1	package org.springframework.samples.petclinic.util;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	import org.springframework.samples.petclinic.model.Owner;
8	
9	/**
10	 * Derives an owner's {@code identityKey} - the single value all duplicate detection is expressed
11	 * through. It is the lower-case hex {@code SHA-256} of
12	 * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}, where the telephone is
13	 * the owner's stored E.164 form, the email is its stored lower-cased form (empty when absent) and
14	 * the last name is reduced to its {@link Soundex} code. Two owners are duplicates when, and only
15	 * when, their identity keys are equal; because the telephone is part of the key, household members
16	 * with different telephones have different keys and are not hard duplicates.
17	 */
18	public final class OwnerIdentity {
19	
20	    private OwnerIdentity() {
21	    }
22	
23	    /**
24	     * @param owner the owner whose identity key to derive.
25	     * @return the 64-character lower-case hex SHA-256 identity key.
26	     */
27	    public static String key(Owner owner) {
28	        String raw = segment(owner.getTelephone()) + "|" + segment(owner.getEmail()).toLowerCase()
29	                + "|" + Soundex.of(owner.getLastName());
30	        return sha256hex(raw);
31	    }
32	
33	    private static String segment(String value) {
34	        return value == null ? "" : value;
35	    }
36	
37	    private static String sha256hex(String value) {
38	        try {
39	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
40	            StringBuilder sb = new StringBuilder(digest.length * 2);
41	            for (byte b : digest) {
42	                sb.append(String.format("%02x", b));
43	            }
44	            return sb.toString();
45	        }
46	        catch (NoSuchAlgorithmException e) {
47	            throw new IllegalStateException("SHA-256 unavailable", e);
48	        }
49	    }
50	}
