17	package org.springframework.samples.petclinic.util;
18	
19	import java.util.Set;
20	
21	import org.springframework.samples.petclinic.model.Owner;
22	
23	/**
24	 * Derives an owner's segment, formatted {@code <TIER>_<AREA>}. TIER is {@code PREMIUM}
25	 * when the {@link MembershipLevel} is 3 or more, otherwise {@code STANDARD}. AREA is
26	 * {@code METRO} when the {@link CustomerCode#regionOf(Owner) locality} is a known region
27	 * (NSW, VIC or QLD), otherwise {@code REGIONAL}. The four possible values are therefore
28	 * {@code PREMIUM_METRO}, {@code PREMIUM_REGIONAL}, {@code STANDARD_METRO} and
29	 * {@code STANDARD_REGIONAL}.
30	 */
31	public final class OwnerSegment {
32	
33	    /** Membership level at or above which the owner is in the PREMIUM tier. */
34	    private static final int PREMIUM_LEVEL = 3;
35	
36	    /** Regions treated as METRO areas. */
37	    private static final Set<String> METRO_REGIONS = Set.of("NSW", "VIC", "QLD");
38	
39	    private OwnerSegment() {
40	    }
41	
42	    /**
43	     * @param owner the owner whose segment to derive.
44	     * @return the segment formatted {@code <TIER>_<AREA>}.
45	     */
46	    public static String of(Owner owner) {
47	        String tier = MembershipLevel.of(owner) >= PREMIUM_LEVEL ? "PREMIUM" : "STANDARD";
48	        String area = METRO_REGIONS.contains(CustomerCode.regionOf(owner)) ? "METRO" : "REGIONAL";
49	        return tier + "_" + area;
50	    }
51	}
