17	package org.springframework.samples.petclinic.util;
18	
19	import java.time.LocalDate;
20	
21	import org.springframework.samples.petclinic.model.Owner;
22	import org.springframework.samples.petclinic.util.FiscalYear;
23	
24	/**
25	 * Derives an owner's membership from a points system. Starts at 0 points, adds 2 when an
26	 * email is present, adds 1 when {@code namesakeCount} is 0, adds 2 for a household of 3 or
27	 * more, and adds 3 when tenure exceeds {@value #TENURE_FISCAL_YEARS} elapsed fiscal year(s).
28	 * Points map to a numeric level: 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more.
29	 * Because level 4 requires 6 points and the only route to 6 is tenure, a newly created owner
30	 * (zero tenure) never exceeds level 3.
31	 */
32	public final class MembershipLevel {
33	
34	    /** Household size, in members, at or above which the household factor applies. */
35	    private static final int HOUSEHOLD_SIZE = 3;
36	
37	    /** Tenure, in elapsed fiscal years, that must be exceeded for the tenure factor to apply. */
38	    private static final int TENURE_FISCAL_YEARS = 1;
39	
40	    private MembershipLevel() {
41	    }
42	
43	    /**
44	     * @param owner the owner whose points to derive (its {@code email},
45	     *              {@code namesakeCount}, {@code householdSize} and tenure decide the points).
46	     * @return the membership points, 0 or more.
47	     */
48	    public static int points(Owner owner) {
49	        int points = 0;
50	        if (owner.getEmail() != null && !owner.getEmail().isEmpty()) {
51	            points += 2;
52	        }
53	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
54	            points += 1;
55	        }
56	        if (owner.getHouseholdSize() != null && owner.getHouseholdSize() >= HOUSEHOLD_SIZE) {
57	            points += 2;
58	        }
59	        if (tenureFiscalYears(owner) > TENURE_FISCAL_YEARS) {
60	            points += 3;
61	        }
62	        return points;
63	    }
64	
65	    /**
66	     * @param owner the owner whose level to derive.
67	     * @return the membership level, from 1 to 4, mapped from {@link #points(Owner)}, then
68	     *         capped by the owner's {@code membershipLevelCap} when one is set (see
69	     *         {@code AssignMembershipCap}). A null cap leaves the level unchanged.
70	     */
71	    public static int of(Owner owner) {
72	        int level = level(points(owner));
73	        Integer cap = owner.getMembershipLevelCap();
74	        if (cap != null && level > cap) {
75	            return cap;
76	        }
77	        return level;
78	    }
79	
80	    /** Maps points to the uncapped numeric level: 1 for 0-1 points, 2 for 2-3, 3 for 4-5, 4 for 6+. */
81	    private static int level(int points) {
82	        if (points <= 1) {
83	            return 1;
84	        }
85	        if (points <= 3) {
86	            return 2;
87	        }
88	        if (points <= 5) {
89	            return 3;
90	        }
91	        return 4;
92	    }
93	
94	    /**
95	     * Elapsed fiscal years from the owner's {@code registrationDate} to today (the number of
96	     * 1-July boundaries crossed since registration), or 0 when unknown.
97	     */
98	    private static long tenureFiscalYears(Owner owner) {
99	        LocalDate registrationDate = owner.getRegistrationDate();
100	        if (registrationDate == null) {
101	            return 0;
102	        }
103	        return FiscalYear.elapsed(registrationDate, LocalDate.now());
104	    }
105	}
