1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.HashSet;
4	import java.util.Set;
5	
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.repository.OwnerRepository;
9	import org.springframework.samples.petclinic.util.CustomerCode;
10	
11	/**
12	 * Assigns the {@code customerCode} to a newly built owner, formatted {@code <REGION>-<HASH8>}
13	 * where REGION is the region derived from the owner's postcode (with a city fallback) and HASH8 is
14	 * the first 8 upper-case hex characters of SHA-256 over the owner's normalized telephone and last
15	 * name (e.g. {@code NSW-1A2B3C4D}). The code is a pure function of the owner's own fields, so it no
16	 * longer depends on how many owners already exist and carries no sequence number.
17	 *
18	 * <p>Should the computed code collide with an existing owner's {@code customerCode}, it is
19	 * de-duplicated by appending {@code -<n>} with the smallest {@code n} of 2 or more that makes it
20	 * unique. This runs before the owner is saved, so it compares against the owners that already
21	 * exist and excludes the owner being created.
22	 */
23	public class AssignCustomerCode {
24	
25	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
26	        String base = CustomerCode.of(owner);
27	
28	        Set<String> existing = new HashSet<>();
29	        for (Owner other : ownerRepository.findAll()) {
30	            String code = other.getCustomerCode();
31	            if (code != null) {
32	                existing.add(code);
33	            }
34	        }
35	
36	        String code = base;
37	        for (int n = 2; existing.contains(code); n++) {
38	            code = base + "-" + n;
39	        }
40	        owner.setCustomerCode(code);
41	    }
42	}
