1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.slf4j.Logger;
5	import org.slf4j.LoggerFactory;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.util.FiscalYear;
8	import org.springframework.samples.petclinic.util.MembershipLevel;
9	
10	/**
11	 * Emits the audit trail for a newly created owner. Runs after the owner has been saved so the
12	 * assigned id is available. Two things are published to the dedicated {@code AUDIT} logger:
13	 * <ol>
14	 * <li>a human-readable line carrying the owner id, the customerCode, the registrationDate, the
15	 * numeric membershipLevel and the membershipNumber; and</li>
16	 * <li>an immutable structured {@link OwnerCreatedEvent} (as JSON) carrying a monotonic sequence
17	 * number, the owner id, the owner's current primary identifier and the membershipLevel.</li>
18	 * </ol>
19	 */
20	public class AuditOwnerCreated {
21	
22	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
23	
24	    public void service(@Val Owner owner) {
25	        int membershipLevel = MembershipLevel.of(owner);
26	        String membershipNumber = String.format("%s-M%02d", owner.getCustomerCode(),
27	                FiscalYear.yearSegment(owner.getRegistrationDate()));
28	        AUDIT.info(
29	                "Owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
30	                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
31	                membershipLevel, membershipNumber);
32	
33	        // The event carries the owner's CURRENT primary identifier — the customerCode today; when a
34	        // later checkpoint unifies it into the memberId, feed the memberId here instead.
35	        OwnerCreatedEvent event = OwnerCreatedEvent.of(owner.getId(), owner.getCustomerCode(), membershipLevel);
36	        AUDIT.info(event.toJson());
37	    }
38	}
