1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;
7	import org.springframework.samples.petclinic.util.OwnerIdentity;
8	
9	/**
10	 * The single duplicate-detection step for the create-owner pipeline: it rejects a request whose
11	 * derived {@code identityKey} - the SHA-256 over
12	 * {@code normalizedTelephone|lowerEmail|soundex(lastName)} - exactly equals an existing owner's.
13	 * This one check subsumes the former separate telephone, email and household checks.
14	 *
15	 * <p>The email-domain blocklist is applied earlier by {@link ValidateOwnerFields} (a blocklisted
16	 * domain is a 400 before this step runs), so identity comparison never sees a blocklisted email.
17	 *
18	 * <p>Runs after {@link BuildOwner}, so the new owner's telephone and email are normalized - the key
19	 * is compared against every other owner's key. A soft-deleted owner is ignored, so its key never
20	 * blocks a new create. Because the telephone is part of the key, two owners with the same last name
21	 * and postcode but different telephones have different keys and both are allowed (they become a soft
22	 * match later); only an exact whole-key match is a duplicate. Throws
23	 * {@link DuplicateIdentityException} (handled as 409) on a collision.
24	 */
25	public class CheckOwnerIdentityUnique {
26	
27	    public void service(@Val Owner owner, OwnerRepository ownerRepository)
28	            throws DuplicateIdentityException {
29	        String identityKey = OwnerIdentity.key(owner);
30	        for (Owner existing : ownerRepository.findAll()) {
31	            // The owner being created is not yet persisted, so findAll() returns only other owners.
32	            // A soft-deleted owner is ignored, so its key never blocks a new create.
33	            if (Boolean.TRUE.equals(existing.getDeleted())) {
34	                continue;
35	            }
36	            if (identityKey.equals(OwnerIdentity.key(existing))) {
37	                throw new DuplicateIdentityException(identityKey);
38	            }
39	        }
40	    }
41	}
