17	package org.springframework.samples.petclinic.util;
18	
19	import java.util.Map;
20	import java.util.regex.Pattern;
21	
22	/**
23	 * Derives an owner's locality (region). The postcode is preferred: the region is
24	 * looked up by postcode range first (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099),
25	 * and only when the postcode is absent or falls in no known range does derivation
26	 * fall back to the fixed city-to-region table. Anything unresolved is
27	 * {@code "UNKNOWN"}.
28	 */
29	public final class Locality {
30	
31	    private static final Pattern FOUR_DIGITS = Pattern.compile("^[0-9]{4}$");
32	
33	    /** City -> canonical region; anything not listed resolves to "UNKNOWN". */
34	    private static final Map<String, String> CITY_REGION = Map.of(
35	            "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
36	
37	    /** Region -> inclusive 4-digit postcode range {low, high}. */
38	    private static final Map<String, int[]> REGION_RANGE = Map.of(
39	            "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
40	
41	    /** Value returned for any locality that cannot be resolved. */
42	    public static final String UNKNOWN = "UNKNOWN";
43	
44	    private Locality() {
45	    }
46	
47	    /**
48	     * @param city the owner's city (may be {@code null}).
49	     * @return the canonical region for {@code city}, or {@code "UNKNOWN"} when the
50	     *         city is not in the fixed table.
51	     */
52	    public static String of(String city) {
53	        return CITY_REGION.getOrDefault(city, UNKNOWN);
54	    }
55	
56	    /**
57	     * Derives the region preferring the postcode: the region whose range contains
58	     * {@code postcode} wins, and only when the postcode is absent or in no known
59	     * range does the city-to-region table decide.
60	     *
61	     * @param postcode the owner's postcode (may be {@code null} or blank).
62	     * @param city     the owner's city (may be {@code null}).
63	     * @return the canonical region, or {@code "UNKNOWN"} when neither resolves.
64	     */
65	    public static String of(String postcode, String city) {
66	        String byPostcode = byPostcode(postcode);
67	        return byPostcode != null ? byPostcode : of(city);
68	    }
69	
70	    /** The region whose range contains {@code postcode}, or {@code null} when none does. */
71	    private static String byPostcode(String postcode) {
72	        if (postcode == null || postcode.isBlank()) {
73	            return null;
74	        }
75	        String trimmed = postcode.trim();
76	        if (!FOUR_DIGITS.matcher(trimmed).matches()) {
77	            return null;
78	        }
79	        int value = Integer.parseInt(trimmed);
80	        for (Map.Entry<String, int[]> entry : REGION_RANGE.entrySet()) {
81	            int[] range = entry.getValue();
82	            if (value >= range[0] && value <= range[1]) {
83	                return entry.getKey();
84	            }
85	        }
86	        return null;
87	    }
88	}
89

1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.concurrent.atomic.AtomicLong;
4	
5	/**
6	 * Immutable, structured audit event for a newly created owner, emitted (as JSON) to the
7	 * {@code AUDIT} logger alongside the human-readable audit line.
8	 *
9	 * <p>The event carries the owner id and the owner's <em>current primary identifier</em>. Today
10	 * that identifier is the {@code customerCode}; when a later checkpoint unifies the customerCode
11	 * into a {@code memberId}, the caller passes the memberId here instead and the event carries it —
12	 * the shape of the event does not change, only the value fed into {@code customerCode}.
13	 *
14	 * <p>{@code seq} is a process-wide, monotonically increasing sequence across creates: each built
15	 * event takes the next value, so the order and count of creates is recoverable from the log.
16	 */
17	public record OwnerCreatedEvent(long seq, Integer ownerId, String customerCode, int membershipLevel,
18	        String event) {
19	
20	    /** The single event marker this type emits. */
21	    public static final String OWNER_CREATED = "OWNER_CREATED";
22	
23	    /** Process-wide monotonic sequence across all created owners. */
24	    private static final AtomicLong SEQUENCE = new AtomicLong();
25	
26	    /**
27	     * Build the next event for a saved owner.
28	     *
29	     * @param ownerId           the saved owner's id.
30	     * @param customerCode      the owner's current primary identifier (customerCode today).
31	     * @param membershipLevel   the owner's effective membership level.
32	     * @return an event stamped with the next sequence number.
33	     */
34	    public static OwnerCreatedEvent of(Integer ownerId, String customerCode, int membershipLevel) {
35	        return new OwnerCreatedEvent(SEQUENCE.incrementAndGet(), ownerId, customerCode, membershipLevel,
36	                OWNER_CREATED);
37	    }
38	
39	    /** Render this event as a compact JSON object. */
40	    public String toJson() {
41	        return "{"
42	                + "\"seq\":" + this.seq
43	                + ",\"ownerId\":" + this.ownerId
44	                + ",\"customerCode\":" + quote(this.customerCode)
45	                + ",\"membershipLevel\":" + this.membershipLevel
46	                + ",\"event\":" + quote(this.event)
47	                + "}";
48	    }
49	
50	    private static String quote(String s) {
51	        if (s == null) {
52	            return "null";
53	        }
54	        StringBuilder sb = new StringBuilder(s.length() + 2).append('"');
55	        for (int i = 0; i < s.length(); i++) {
56	            char c = s.charAt(i);
57	            switch (c) {
58	                case '"' -> sb.append("\\\"");
59	                case '\\' -> sb.append("\\\\");
60	                case '\n' -> sb.append("\\n");
61	                case '\r' -> sb.append("\\r");
62	                case '\t' -> sb.append("\\t");
63	                default -> sb.append(c);
64	            }
65	        }
66	        return sb.append('"').toString();
67	    }
